const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "// Eventr data model.\n//\n// One organisation runs many events. One event = one QR + one entry form +\n// an ordered list of prizes. Guests create entries; the live draw turns\n// entries into winners and records how it did it.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------------------\n// Organisation, people and access\n// ---------------------------------------------------------------------------\n\nenum Role {\n  OWNER\n  EDITOR\n  VIEWER\n  KIOSK\n}\n\nenum RetentionPeriod {\n  DAYS_7\n  DAYS_30\n  DAYS_90\n  MONTHS_12\n}\n\nmodel Organisation {\n  id           String  @id @default(cuid())\n  name         String\n  logoKey      String?\n  accentColour String  @default(\"#6F5CF0\")\n  replyToEmail String?\n\n  // Privacy & data settings (screen 4d). Events inherit these.\n  retentionPeriod       RetentionPeriod @default(DAYS_30)\n  minimiseByDefault     Boolean         @default(true)\n  maskNamesOnScreen     Boolean         @default(true)\n  marketingOptInEnabled Boolean         @default(false)\n  autoFulfilErasure     Boolean         @default(false)\n\n  // Which version of the DPA and Terms were accepted, by whom and when.\n  dpaVersion      String?\n  dpaAcceptedAt   DateTime?\n  dpaAcceptedById String?\n  termsVersion    String?\n  termsAcceptedAt DateTime?\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  memberships     Membership[]\n  events          Event[]\n  invites         Invite[]\n  consentVersions ConsentTextVersion[]\n  auditLogs       AuditLog[]\n\n  @@index([deletedAt])\n}\n\nmodel User {\n  id        String  @id @default(cuid())\n  email     String  @unique\n  firstName String?\n  lastName  String?\n  locale    String  @default(\"en\")\n  timeZone  String  @default(\"Europe/Berlin\")\n\n  // Organiser preference behind \"Turn off reminders\" in the reminder email.\n  remindersEnabled Boolean @default(true)\n\n  totpSecret        String?\n  totpEnabledAt     DateTime?\n  totpRecoveryCodes String[]  @default([])\n\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n  lastSeenAt DateTime?\n\n  memberships Membership[]\n  sessions    Session[]\n  magicLinks  MagicLink[]\n  sentInvites Invite[]     @relation(\"InviteSender\")\n  auditLogs   AuditLog[]\n}\n\nmodel Membership {\n  id             String @id @default(cuid())\n  userId         String\n  organisationId String\n  role           Role\n\n  // \"Limit to one event\" in the invite modal (screen 7g).\n  scopedEventId String?\n\n  createdAt DateTime @default(now())\n\n  user         User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  organisation Organisation @relation(fields: [organisationId], references: [id], onDelete: Cascade)\n  scopedEvent  Event?       @relation(\"MembershipScope\", fields: [scopedEventId], references: [id], onDelete: SetNull)\n\n  @@unique([userId, organisationId])\n  @@index([organisationId])\n}\n\nmodel Session {\n  id             String  @id @default(cuid())\n  tokenHash      String  @unique\n  userId         String\n  organisationId String?\n\n  userAgent String?\n  ipHash    String?\n  label     String?\n\n  createdAt    DateTime  @default(now())\n  lastActiveAt DateTime  @default(now())\n  expiresAt    DateTime\n  revokedAt    DateTime?\n\n  // Set once the TOTP challenge has been passed, when 2FA is enabled.\n  mfaSatisfiedAt DateTime?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\nmodel MagicLink {\n  id        String  @id @default(cuid())\n  tokenHash String  @unique\n  email     String\n  userId    String?\n\n  // Where to land after sign-in, and which waiting tab to release over SSE.\n  redirectTo String?\n  channelId  String  @unique @default(cuid())\n\n  createdAt  DateTime  @default(now())\n  expiresAt  DateTime\n  consumedAt DateTime?\n  requestIp  String?\n\n  user User? @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([email, createdAt])\n  @@index([expiresAt])\n}\n\nmodel Invite {\n  id             String  @id @default(cuid())\n  tokenHash      String  @unique\n  organisationId String\n  email          String\n  role           Role\n  scopedEventId  String?\n  invitedById    String?\n\n  createdAt  DateTime  @default(now())\n  expiresAt  DateTime\n  acceptedAt DateTime?\n  revokedAt  DateTime?\n\n  organisation Organisation @relation(fields: [organisationId], references: [id], onDelete: Cascade)\n  invitedBy    User?        @relation(\"InviteSender\", fields: [invitedById], references: [id], onDelete: SetNull)\n\n  @@index([organisationId, email])\n}\n\n// A booth iPad or laptop paired with a short code (screen 7g). It can only\n// reach the QR screen and the live draw, and never receives personal data.\nmodel KioskPairing {\n  id        String    @id @default(cuid())\n  code      String    @unique\n  eventId   String\n  createdAt DateTime  @default(now())\n  expiresAt DateTime\n  claimedAt DateTime?\n\n  event  Event        @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  device KioskDevice?\n}\n\nmodel KioskDevice {\n  id        String  @id @default(cuid())\n  tokenHash String  @unique\n  eventId   String\n  pairingId String? @unique\n  label     String?\n\n  createdAt  DateTime  @default(now())\n  lastSeenAt DateTime?\n  expiresAt  DateTime\n  revokedAt  DateTime?\n\n  event   Event         @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  pairing KioskPairing? @relation(fields: [pairingId], references: [id], onDelete: SetNull)\n\n  @@index([eventId])\n}\n\n// ---------------------------------------------------------------------------\n// Events, form fields and prizes\n// ---------------------------------------------------------------------------\n\nenum EventStatus {\n  DRAFT\n  PUBLISHED\n  CLOSED\n  COMPLETED\n}\n\nenum FieldType {\n  TEXT\n  EMAIL\n  PHONE\n  COMPANY\n  CHOICE\n  CHECKBOX\n}\n\nenum DrawAnimation {\n  NAME_REEL\n  WHEEL\n  COUNTDOWN\n  CARDS\n}\n\nmodel Event {\n  id             String      @id @default(cuid())\n  organisationId String\n  slug           String      @unique\n  name           String\n  status         EventStatus @default(DRAFT)\n\n  eventDate      DateTime?\n  entriesCloseAt DateTime?\n  drawAt         DateTime?\n  welcomeMessage String?\n  venueLabel     String?\n\n  // Branding overrides; null means inherit from the organisation.\n  logoKey             String?\n  accentColour        String?\n  backgroundColour    String?\n  screenBackgroundKey String?\n\n  // Live draw settings (screen 1f).\n  animation        DrawAnimation @default(NAME_REEL)\n  suspenseSeconds  Int           @default(6)\n  showLogo         Boolean       @default(true)\n  showEntryCount   Boolean       @default(true)\n  maskPersonalData Boolean       @default(true)\n  confettiOnWin    Boolean       @default(true)\n  redrawEnabled    Boolean       @default(true)\n\n  // Per-event retention, defaulting to the organisation's setting.\n  retentionPeriod RetentionPeriod?\n  claimWindow     ClaimWindow      @default(TODAY)\n\n  nextEntryNumber Int @default(1)\n\n  publishedAt DateTime?\n  closedAt    DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  deletedAt   DateTime?\n\n  organisation      Organisation   @relation(fields: [organisationId], references: [id], onDelete: Cascade)\n  fields            FormField[]\n  prizes            Prize[]\n  entries           Entry[]\n  winners           Winner[]\n  drawLogs          DrawLog[]\n  guestRequests     GuestRequest[]\n  kioskPairings     KioskPairing[]\n  kioskDevices      KioskDevice[]\n  scopedMemberships Membership[]   @relation(\"MembershipScope\")\n\n  @@index([organisationId, createdAt])\n  @@index([status, entriesCloseAt])\n}\n\nmodel FormField {\n  id       String    @id @default(cuid())\n  eventId  String\n  key      String\n  label    String\n  type     FieldType\n  required Boolean   @default(false)\n  order    Int\n  options  String[]  @default([])\n\n  // Set when the organiser enabled a field the minimisation default hides.\n  justification String?\n\n  event Event @relation(fields: [eventId], references: [id], onDelete: Cascade)\n\n  @@unique([eventId, key])\n  @@index([eventId, order])\n}\n\nmodel Prize {\n  id          String  @id @default(cuid())\n  eventId     String\n  order       Int\n  name        String\n  meta        String?\n  winnerCount Int     @default(1)\n\n  event   Event    @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  winners Winner[]\n\n  @@index([eventId, order])\n}\n\n// ---------------------------------------------------------------------------\n// Guest entries\n// ---------------------------------------------------------------------------\n\nmodel Entry {\n  id      String @id @default(cuid())\n  eventId String\n  number  Int\n\n  // Answers keyed by FormField.key. Personal data lives here and is what an\n  // erasure request clears.\n  data Json @default(\"{}\")\n\n  // Denormalised for duplicate detection and notification, normalised on write.\n  email String?\n  phone String?\n  name  String?\n\n  isDuplicate     Boolean @default(false)\n  duplicateOfId   String?\n  duplicateManual Boolean @default(false)\n\n  // The exact wording, version and moment the guest agreed to.\n  consentText    String\n  consentVersion String\n  consentedAt    DateTime\n  marketingOptIn Boolean  @default(false)\n\n  // Unguessable token so the guest can reopen their own confirmation page.\n  accessToken String @unique @default(cuid())\n\n  createdAt DateTime  @default(now())\n  erasedAt  DateTime?\n\n  event         Event          @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  duplicateOf   Entry?         @relation(\"EntryDuplicate\", fields: [duplicateOfId], references: [id], onDelete: SetNull)\n  duplicates    Entry[]        @relation(\"EntryDuplicate\")\n  winner        Winner?\n  guestRequests GuestRequest[]\n\n  @@unique([eventId, number])\n  @@index([eventId, createdAt])\n  @@index([eventId, email])\n  @@index([eventId, phone])\n}\n\n// ---------------------------------------------------------------------------\n// Draw, winners and the audit trail\n// ---------------------------------------------------------------------------\n\nenum ClaimWindow {\n  MINUTES_15\n  HOUR_1\n  TODAY\n  DAYS_7\n}\n\nmodel Winner {\n  id      String @id @default(cuid())\n  eventId String\n  prizeId String\n  entryId String @unique\n\n  drawnAt       DateTime  @default(now())\n  claimCode     String\n  claimDeadline DateTime?\n\n  notifiedEmailAt DateTime?\n  notifiedSmsAt   DateTime?\n  deliveredAt     DateTime?\n\n  // Set when this winner was superseded by a re-draw.\n  supersededAt     DateTime?\n  supersededReason String?\n\n  accessToken String @unique @default(cuid())\n\n  event Event @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  prize Prize @relation(fields: [prizeId], references: [id], onDelete: Cascade)\n  entry Entry @relation(fields: [entryId], references: [id], onDelete: Cascade)\n\n  @@index([eventId, drawnAt])\n  @@index([prizeId])\n}\n\n// Append-only. This is what makes \"provably fair\" more than a slogan: it\n// records the pool a winner came from without keeping the pool's personal data.\nmodel DrawLog {\n  id      String  @id @default(cuid())\n  eventId String\n  prizeId String?\n\n  algorithm       String\n  eligibleCount   Int\n  eligibleHash    String\n  selectedEntryId String?\n  selectedNumber  Int?\n\n  // Set on a re-draw, naming the winner that was replaced.\n  supersededWinnerId String?\n  reason             String?\n\n  triggeredByUserId String?\n  drawnOffline      Boolean  @default(false)\n  createdAt         DateTime @default(now())\n\n  event Event @relation(fields: [eventId], references: [id], onDelete: Cascade)\n\n  @@index([eventId, createdAt])\n}\n\n// ---------------------------------------------------------------------------\n// GDPR: consent versioning, guest requests, audit\n// ---------------------------------------------------------------------------\n\nmodel ConsentTextVersion {\n  id             String   @id @default(cuid())\n  organisationId String\n  version        String\n  template       String\n  createdAt      DateTime @default(now())\n\n  organisation Organisation @relation(fields: [organisationId], references: [id], onDelete: Cascade)\n\n  @@unique([organisationId, version])\n}\n\nenum GuestRequestType {\n  EXPORT\n  ERASE\n}\n\nenum GuestRequestStatus {\n  OPEN\n  FULFILLED\n  REJECTED\n}\n\nmodel GuestRequest {\n  id      String             @id @default(cuid())\n  eventId String\n  entryId String?\n  type    GuestRequestType\n  status  GuestRequestStatus @default(OPEN)\n\n  requestedAt DateTime  @default(now())\n  dueAt       DateTime\n  fulfilledAt DateTime?\n  note        String?\n\n  event Event  @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  entry Entry? @relation(fields: [entryId], references: [id], onDelete: SetNull)\n\n  @@index([eventId, status])\n}\n\nmodel AuditLog {\n  id             String  @id @default(cuid())\n  organisationId String?\n  userId         String?\n  action         String\n  targetType     String?\n  targetId       String?\n  detail         Json?\n\n  createdAt DateTime @default(now())\n\n  organisation Organisation? @relation(fields: [organisationId], references: [id], onDelete: SetNull)\n  user         User?         @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([organisationId, createdAt])\n}\n\nmodel EmailLog {\n  id         String    @id @default(cuid())\n  template   String\n  toEmail    String\n  subject    String\n  providerId String?\n  status     String    @default(\"queued\")\n  error      String?\n  dedupeKey  String?   @unique\n  sentAt     DateTime?\n  createdAt  DateTime  @default(now())\n\n  @@index([toEmail, createdAt])\n}\n\n// Idempotency ledger for the in-process scheduler (reminders, retention,\n// auto-close). One row per job per due window, so a restart cannot double-send.\nmodel JobRun {\n  id         String    @id @default(cuid())\n  job        String\n  key        String\n  startedAt  DateTime  @default(now())\n  finishedAt DateTime?\n  error      String?\n\n  @@unique([job, key])\n}\n"
}

